CREATE TABLE IF NOT EXISTS p12_world_boss_cycles(id VARCHAR(64) PRIMARY KEY,window_key VARCHAR(64) NOT NULL,state VARCHAR(16) NOT NULL,starts_at BIGINT NOT NULL,ends_at BIGINT NOT NULL,definition_json LONGTEXT NOT NULL,definition_hash VARCHAR(64) NOT NULL,level BIGINT NOT NULL,position_id BIGINT NOT NULL,created_at BIGINT NOT NULL,activated_at BIGINT NOT NULL,ended_at BIGINT NOT NULL,UNIQUE KEY idx_p12_world_window(window_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
